function isPublicHostname(hostname){const h=String(hostname||'').trim().toLowerCase().replace(/\.$/,'');if(!h||h==='localhost'||h.endsWith('.localhost')||h.endsWith('.local')||h.endsWith('.internal'))return false;if(h==='0.0.0.0'||h==='::1'||h==='[::1]'||/^127\./.test(h)||/^10\./.test(h)||/^192\.168\./.test(h)||/^169\.254\./.test(h))return false;const m=h.match(/^172\.(\d+)\./);return !(m&&+m[1]>=16&&+m[1]<=31)}
