const PROVIDERS={firebase:[/firebase\/auth|firebase-auth|firebaseapp\.com|identitytoolkit\.googleapis\.com|securetoken\.googleapis\.com|firebaseinstallations\.googleapis\.com/i,/signInWithEmailAndPassword|onAuthStateChanged|getAuth\s*\(|initializeAuth\s*\(|authDomain\s*[:=]/i],supabase:[/\.supabase\.co|@supabase\/supabase-js|supabase-js|signInWithPassword|signInWithOtp/i],auth0:[/\.auth0\.com|@auth0|createAuth0Client|Auth0Client/i],clerk:[/clerk\.com|@clerk|clerkpublishablekey|clerk-js/i],cognito:[/cognito-idp|amazoncognito|CognitoUserPool|aws-amplify\/auth|UserPoolId/i],okta:[/\.okta\.com|@okta|OktaAuth|okta-auth-js/i],'entra-id':[/login\.microsoftonline\.com|@azure\/msal|PublicClientApplication/i],keycloak:[/keycloak-js|new\s+Keycloak|\/realms\/[^/]+\/protocol\/openid-connect/i],authjs:[/next-auth|nextauth|authjs|\/api\/auth\/(signin|session|callback)/i],passport:[/passport\.authenticate|passport-local|passport-jwt/i],'jwt-custom':[/Authorization\s*[:=]\s*["'`]Bearer|jwt\.sign|jwt\.verify|jsonwebtoken|refresh[_-]?token/i],oauth2:[/grant_type|redirect_uri|response_type|code_challenge|\/authorize|\/oauth(?:2)?\//i],oidc:[/openid-configuration|openid-connect|id_token|jwks_uri|userinfo_endpoint/i]};
