function scoreEndpoint(ep,sm,em){const e=String(ep).toLowerCase();const rules=[['firebase',/identitytoolkit\.googleapis\.com|securetoken\.googleapis\.com|firebaseapp\.com|\.web\.app/],['supabase',/\.supabase\.co/],['auth0',/\.auth0\.com/],['clerk',/clerk\./],['cognito',/amazoncognito|cognito-idp/],['okta',/\.okta\.com/],['entra-id',/microsoftonline\.com/],['keycloak',/\/realms\/|openid-connect/]];for(const[p,re]of rules)if(re.test(e))addScore(sm,em,p,5,`endpoint/origem: ${ep}`)}
function scoreCookies(names,sm,em){for(const name of names){const n=String(name).toLowerCase();if(/next-auth|authjs/.test(n))addScore(sm,em,'authjs',5,`cookie: ${name}`);if(/^sb-.*-auth-token$/.test(n))addScore(sm,em,'supabase',5,`cookie: ${name}`);if(/clerk|__session/.test(n))addScore(sm,em,'clerk',3,`cookie: ${name}`);if(/okta/.test(n))addScore(sm,em,'okta',4,`cookie: ${name}`);if(/keycloak/.test(n))addScore(sm,em,'keycloak',4,`cookie: ${name}`)}}
async function firebaseRuntimeConfig(base){const candidates=['/__/firebase/init.json','/__/firebase/init.js'];for(const path of candidates){try{const f=await fetchText(new URL(path,base));if(!f.ok||!f.text)continue;if(path.endsWith('.json')){const d=JSON.parse(f.text);return{apiKey:d.apiKey||'',authDomain:d.authDomain||'',projectId:d.projectId||'',source:path}}const cfg=extractFirebaseConfig(f.text);if(cfg.apiKey||cfg.authDomain||cfg.projectId)return{...cfg,source:path}}catch{}}return null}
